contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take parameters to set MinSum, deposit amount, and collect amount.
    // The test will: set MinSum, deposit some ether (amountDep), then attempt Collect(amountCollect).
    // The assertion: if the depositor's stored balance before Collect is strictly less than MinSum,
    // then address(c).balance after Collect is >= address(c).balance before Collect (i.e., contract does not lose Ether).

    function run(uint _minSum, uint amountDep, uint amountCollect) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amountDep)); require(amountDep <= 1000000000000000000000000000000);
        require(address(this).balance >= amountDep, "insufficient test balance");
        // Initialize MinSum and Log only before Initialized() is called by C; we assume fresh c so intitalized==false
        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;

        // Deposit amountDep into c from this contract
        c.Deposit{value: amountDep}(); if (__ESBMC_reverted()) return;

        // Read the caller's recorded balance (this contract is msg.sender for calls to c)
        uint bal_before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contract_eth_before = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        c.Collect(amountCollect); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint contract_eth_after = address(c).balance;

        // General rule: if stored balance before Collect is strictly less than MinSum,
        // then the contract's Ether balance must not decrease (no Ether sent out).
        assert(!(bal_before < c.MinSum() ) || contract_eth_after >= contract_eth_before);
    }

    // Allow this test contract to receive Ether so it can call c.Deposit
    receive() external payable {}
}

