// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _minSum, uint256 amountDep, uint256 amountCollect) internal {
        amountDep = bound(amountDep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amountDep);
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Deposit{value: amountDep}() {} catch { return; }
        uint256 bal_before;
        try c.balances(address(this)) returns (uint256 __r) { bal_before = __r; } catch { return; }
        uint contract_eth_before = address(c).balance;
        bool reverted;
        try c.Collect(amountCollect) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint contract_eth_after = address(c).balance;
        assertTrue(!(bal_before < c.MinSum() ) || contract_eth_after >= contract_eth_before);
    }

    function testFuzz_run(uint256 _minSum, uint256 amountDep, uint256 amountCollect) public {
        _run(_minSum, amountDep, amountCollect);
    }

    receive() external payable {}
}
